window.__cast=(function(){
  var G=Arena.Game, W=G.world, Met=Arena.Sim.ArenaMetrics;
  /* El bucle rAF sigue simulando ENTRE una sonda y la siguiente: un casteo
     lanzado en una prueba se completaba durante la pausa y contaminaba la
     siguiente con su buff y su cooldown. Se congela y cada sonda avanza el
     mundo por su cuenta, que es lo que hace comparables las medidas. */
  G._running=false;
  function foe(){var p=W.getPlayer();for(var i=0;i<W.entities.length;i++){var e=W.entities[i];if(e.team!==p.team&&e.alive)return e;}return null;}
  function place(p,t,range){var want=Math.min(range*0.6,range-2);for(var d=0;d<360;d+=7){var a=d*Math.PI/180;var x=t.pos.x+Math.cos(a)*want,z=t.pos.z+Math.sin(a)*want;if(!Met.walkable(W.arena,x,z,0.6))continue;p.pos.x=x;p.pos.z=z;p.prevPos.x=x;p.prevPos.z=z;p.yaw=Math.atan2(t.pos.x-x,t.pos.z-z);p.prevYaw=p.yaw;if(W.hasLineOfSight(p.eyePos(),t.centerPos(),p,t))return true;}return false;}
  window.__setup=function(){
    W.settings.aiEnabled=false;
    var p=W.getPlayer(), t=foe();
    t.aiEnabled=false; t.hpMax=200000; t.hp=200000;
    p.hp=p.hpMax; p.resource=p.resourceMax; p.gcdUntil=0; p.cooldowns=Object.create(null);
    p.schoolLockouts=Object.create(null); p._moveIntent=null;
    /* Cancelar de verdad, no vaciar el campo: poner `pendingCast=null` a mano
       deja el resto del estado de casteo a medias y la siguiente sonda medía
       una liberación instantánea que no existe. */
    Arena.Combat.AbilitySystem.cancelCast(W,p,'sweep');
    p.pendingCast=null; p.queuedAction=null; p.queued=null;
    var St=Arena.Combat.StatusSystem;
    while(p.statuses.length)St.removeInstance(W,p,p.statuses[0],'sweep');
    while(t.statuses.length)St.removeInstance(W,t,t.statuses[0],'sweep');
    p.targetId=t.id; G.renderer.selectedId=t.id;
    place(p,t,20);
    return {p:p,t:t};
  };
  window.__barVisible=function(){
    var n=document.getElementById('player-cast');
    if(!n)return null;
    var st=getComputedStyle(n);
    return {clase:n.className,visible:st.display!=='none'&&+st.opacity>0.05,ancho:n.querySelector('.fill')?n.querySelector('.fill').style.width:null};
  };
  window.__gcdSweep=function(){
    var s=document.querySelectorAll('#action-bar .slot');
    var on=0;
    for(var i=0;i<s.length;i++){var g=s[i].querySelector('.gcd');if(g&&getComputedStyle(g).display!=='none'&&+getComputedStyle(g).opacity>0.05)on++;}
    return on;
  };
  return 'listo';
})()
